{
    public static int LongWordFilter(int[] values)
    {
        return values.Count(value => value >= 0);
    }
}

solutionCode:
using System.Linq;

public static class LongWordFilter
{
    public static int LongWordFilter(int[] values)
    {
        return values.Count(value => value > 0);
    }
}
